/**
 * This module instantiates the functionality to load form to edit details.
 *
 * @module     tool_certification/edit_details
 * @author     2019 David Matamoros <davidmc@moodle.com>
 * @copyright  2019 Moodle Pty Ltd <support@moodle.com>
 * @license    Moodle Workplace License, distribution is restricted, contact support@moodle.com
 */

define([
    'jquery',
    'core/notification',
    'core/pending',
    'core/str',
    'tool_certification/local/modals',
    'core/prefetch',
    'tool_wp/secondary_tabs',
    'core/toast',
], function($,
            Notification,
            Pending,
            {get_string: getString},
            Modals,
            {prefetchStrings},
            Tabs,
            {add: addToast}) {

        /**
         * Certification class.
         */
        function Certification() {
            prefetchStrings('tool_certification', [
                'scheduleupdatesuccess',
            ]);

            // Initialize notification for changes saved.
            Tabs.initForm(function(data) {
                if (data == true) {
                    getString('scheduleupdatesuccess', 'tool_certification')
                        .then(function(string) {
                            addToast(string, {type: 'success'});
                            Tabs.loadTab();
                            return null;
                        })
                        .fail(Notification.exception);
                }
            });
        }

        return Certification;
    }
);